<!doctype html><meta charset="utf-8"><title>FilaForge grip regression</title><h1>Inline editor grip regression</h1><pre id="result">Running…</pre><iframe id="canvas" style="width:900px;height:500px"></iframe><script>
const frame=document.getElementById('canvas');frame.srcdoc=<?= json_encode(file_get_contents(__DIR__.'/../../resources/views/editor/canvas.blade.php'), JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_THROW_ON_ERROR) ?>;
const node=(id,type,props)=>({id,type,widgetVersion:1,props,styles:[],responsive:[],bindings:[],visibility:[],meta:[],children:[]});
const doc={schemaVersion:1,locale:'fa',direction:'rtl',root:{...node('root','container',{direction:'column'}),children:[node('heading','heading',{tag:'h2',text:'سلام'}),node('text','text',{text:'متن'}),node('rich','rich-text',{html:'<p><strong>متن غنی</strong></p>'}),node('button','button',{text:'دکمه',url:'#'})]}};
let port,pending,results=[];const tick=()=>new Promise(r=>setTimeout(r,40));
frame.onload=()=>{const channel=new MessageChannel();port=channel.port1;port.onmessage=async({data})=>{if(data.type==='ready')run();else if(data.type==='inline'&&pending){const resolve=pending;pending=null;resolve(data)}};frame.contentWindow.postMessage('filaforge-connect','*',[channel.port2])};
async function run(){try{for(const n of doc.root.children){for(let round=0;round<4;round++){port.postMessage({type:'render',document:doc,selected:n.id});await tick();port.postMessage({type:'edit',id:n.id});await tick();const d=frame.contentDocument,el=d.querySelector('[data-node="'+n.id+'"]');if(!el.isContentEditable)throw Error('Not editable: '+n.id);el.append(d.createTextNode(' ✓'));const response=new Promise(r=>pending=r);d.querySelector('[data-command="finish"]').click();const saved=await response;if(saved.value.includes('⠿')||saved.html.includes('⠿')||saved.html.includes('ff-node-grip'))throw Error('Grip persisted: '+n.id);if(n.type==='rich-text')n.props.html=saved.html;else{n.props.text=saved.value;n.props.formatted={text:saved.html}}results.push(n.id+' edit '+(round+1)+': PASS')}}document.getElementById('result').textContent='PASS: 16 consecutive inline edits, no grip text or editor control stored.\n'+results.join('\n')}catch(e){document.getElementById('result').textContent='FAIL: '+e.message}}
</script>